{
  "status": "NEED_INFO",
  "summary": "Dự án LabBooking là một ứng dụng web giúp quản lý việc đặt phòng thí nghiệm, giải quyết vấn đề trùng lịch thông qua hệ thống đăng ký, duyệt yêu cầu và báo cáo dành cho sinh viên và quản trị viên.",
  "deadline": {
    "value": "10/11/2026 23:59",
    "quote": "Mốc giữa kỳ: nộp bản thiết kế cơ sở dữ liệu trước 23:59 ngày 10/11/2026."
  },
  "requirements": [
    {
      "content": "Người dùng đăng ký, đăng nhập bằng email trường và mật khẩu phải được băm (hash).",
      "quote": "Người dùng đăng ký, đăng nhập bằng email trường; mật khẩu phải được băm (hash) trước khi lưu."
    },
    {
      "content": "Sinh viên xem lịch trống theo tuần và thực hiện đặt phòng theo ngày, ca.",
      "quote": "Sinh viên xem lịch trống theo tuần và gửi yêu cầu đặt phòng (chọn phòng, ngày, ca)."
    },
    {
      "content": "Hệ thống tự động ngăn chặn việc đặt trùng các ca đã được duyệt.",
      "quote": "Hệ thống tự động chặn yêu cầu đặt phòng bị trùng với ca đã được duyệt."
    },
    {
      "content": "Quản trị viên có chức năng duyệt/từ chối và hệ thống gửi thông báo cho sinh viên.",
      "quote": "Quản trị viên duyệt hoặc từ chối yêu cầu; sinh viên nhận thông báo kết quả trong ứng dụng."
    },
    {
      "content": "Xuất báo cáo sử dụng phòng theo tháng dưới định dạng CSV.",
      "quote": "Quản trị viên xuất báo cáo tần suất sử dụng từng phòng theo tháng (định dạng CSV)."
