  ],
  "constraints": [
    {
      "content": "Nhóm thực hiện gồm đúng 3 thành viên.",
      "quote": "Bài tập thực hiện theo nhóm 3 sinh viên."
    },
    {
      "content": "Công nghệ: Node.js (Express) hoặc Python (Django); CSDL: MySQL hoặc PostgreSQL.",
      "quote": "Backend sử dụng Node.js (Express) hoặc Python (Django); cơ sở dữ liệu quan hệ (MySQL hoặc PostgreSQL)."
    },
    {
      "content": "Cấm sử dụng các công cụ low-code/no-code.",
      "quote": "Không sử dụng nền tảng low-code/no-code (Firebase, Bubble...)."
    },
    {
      "content": "Giao diện phải tương thích với thiết bị di động (Responsive).",
      "quote": "Giao diện hiển thị tốt trên màn hình điện thoại (responsive)."
    },
    {
      "content": "Quản lý mã nguồn qua Git, tối thiểu mỗi người 10 commit.",
      "quote": "Mã nguồn quản lý bằng Git, mỗi thành viên có tối thiểu 10 commit."
    }
  ],
