      "due": "05/12/2026"
    },
    {
      "step": 5,
      "task": "Xây dựng chức năng Admin (Duyệt lịch, Xuất CSV) và kiểm thử hệ thống.",
      "due": "15/12/2026"
    },
    {
      "step": 6,
      "task": "Viết báo cáo PDF (dưới 20 trang), quay video demo (5 phút) và nộp bài.",
      "due": "20/12/2026"
    }
  ]
